// Local policy patch: an unresolved write destination cannot be checked by
// path_write. Keep that uncertainty visible to the command approval gate.
function hasComputedOutputRedirect(node: TSNode, words: WordReader): boolean {
  if (node.type === "file_redirect") {
    const index = redirectTargetIndex(node);
    const target = index === undefined ? null : node.child(index);
    if (target) {
      const effect = redirectEffectForDestination(node, target);
      if (effect !== null && effect.effect !== "read" && words.argWord(target).computed) {
        return true;
      }
    }
  }
  for (let i = 0; i < node.childCount; i++) {
    const child = node.child(i);
    if (child && hasComputedOutputRedirect(child, words)) return true;
  }
  return false;
}

